// The form stage asks the same session what kind of visual the content needs, before a
// plan is written. The brief is the authoring brief plus the vocabulary (a deck brief
// carries none) and the writer's hint; the writer's answer is not a pin.
const a = $input.first().json || {};
let body = {};
try { body = JSON.parse(String(a.AUTHOR_BODY || '{}')); } catch (e) { body = {}; }
const first = (((body.messages || [])[0] || {}).content);
if (!first) throw new Error('the form stage has no authoring brief to choose a form from');
const forms = String($('visual_forms').first().json.FORMS || '').trim();
const suggested = String(a.SUGGESTED_FORM || '').trim().toLowerCase();
const scenes = String(a.SUGGESTED_SCENES || '').trim();
const hint = [
  suggested ? 'The post writer suggested the ' + suggested + ' form as a hint, not a decision.' : '',
  scenes ? 'The post writer suggested ' + scenes + ' scenes as a hint, not a decision.' : '',
].filter(Boolean);
const content = first
  + (forms && !first.includes(forms) ? '\n\nForm vocabulary:\n' + forms : '')
  + (hint.length ? '\n\n---\n\n' + hint.join(' ') : '');
return [{ json: {
  ...a,
  FORM_BODY: JSON.stringify({ ...body, task: 'forms', options: 3, messages: [{ role: 'user', content }] }),
} }];

// The form options the composer returned, and the critic's request. A rejected option is
// named in FORM_ERROR; the valid ones still travel, because a stage that fell back is
// recorded, not turned into a failed run.
const a = $('build_forms_brief').last().json || {};
const r = $input.first().json || {};
const forms = Array.isArray(r.forms) ? r.forms : [];
const failure = r.error && (r.error.message || r.error);
const error = forms.length ? String(r.error || '') : String(failure || 'the forms turn returned no options');
const prompt = String($('download_form_review_prompt').first().json.output || '').trim();
if (!prompt) throw new Error('the form review prompt is empty; refusing to review the form options');
let body = {};
try { body = JSON.parse(String(a.AUTHOR_BODY || '{}')); } catch (e) { body = {}; }
const brief = String((((body.messages || [])[0] || {}).content) || '');
const human = String(a.HUMAN_FEEDBACK || a.FEEDBACK || '').trim();
const suggested = String(a.SUGGESTED_FORM || '').trim().toLowerCase();
const optionsText = forms.length ? JSON.stringify(forms, null, 2) : '';
const review = [
  prompt,
  '',
  '---',
  '',
  'The post text, the source and the rules the visual is for:',
  brief,
  ...(human ? ['', '---', '', 'Feedback from the person - a requirement:', human] : []),
  ...(suggested ? ['', '---', '', 'The post writer suggested this form, as a hint:', suggested] : []),
  ...(optionsText ? ['', '---', '', "The composer's form options:", optionsText] : ['', '---', '', 'The composer returned no parsable form options.']),
].join('\n');
return [{ json: {
  ...a,
  FORM_OPTIONS: JSON.stringify(forms),
  FORM_ERROR: error,
  FORM_REVIEW_BODY: JSON.stringify({ model: 'opencode-go/minimax-m3', messages: [{ role: 'user', content: review }] }),
} }];

// The form critic's choice. The option it names wins; an unreadable answer, or an id that
// names no option, takes the first valid option and marks the stage as a fallback. With no
// valid option the stage cannot decide, and FORM stays empty so the single-plan path runs.
const a = $('parse_forms').last().json || {};
const resp = $input.first().json || {};
const raw = String((((resp.choices || [])[0] || {}).message || {}).content || '').trim();
let answer = null;
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
if (start !== -1 && end > start) {
  try { const parsed = JSON.parse(raw.slice(start, end + 1)); if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) answer = parsed; } catch (e) { answer = null; }
}
const forms = (() => {
  try { const parsed = JSON.parse(String(a.FORM_OPTIONS || '[]')); return Array.isArray(parsed) ? parsed : []; } catch (e) { return []; }
})();
const choice = answer ? String(answer.choice || '').trim() : '';
const named = forms.find((option) => option && option.id === choice) || null;
const chosen = named || forms[0] || null;
// No option at all is also a fallback: the single-plan path runs and the asset records it.
const fallback = !named;
return [{ json: {
  ...a,
  FORM_OPTIONS: JSON.stringify(forms),
  FORM_CHOICE: chosen ? String(chosen.id) : '',
  FORM: chosen ? String(chosen.form) : '',
  OPTIONS_FALLBACK: a.OPTIONS_FALLBACK === true || fallback,
  NEEDS_REVIEW: a.NEEDS_REVIEW === true || fallback,
  FORM_ERROR: forms.length
    ? String(a.FORM_ERROR || '')
    : (String(a.FORM_ERROR || '') || 'the form stage returned no valid option'),
} }];

// The plan-options turn: the chosen form, the same authoring brief, and the person's
// requirements. The options are storyboards the critic ranks; none is rendered yet.
const a = $input.first().json || {};
let body = {};
try { body = JSON.parse(String(a.AUTHOR_BODY || '{}')); } catch (e) { body = {}; }
const first = (((body.messages || [])[0] || {}).content);
if (!first) throw new Error('the plan-options stage has no authoring brief to plan from');
// A type-declared form and a pinned FORCE are both fixed, so both buy storyboards;
// the form stage has already put its choice on FORM when it ran.
const force = String(a.FORCE || 'auto').trim();
const form = String(a.FORM || (force !== 'auto' ? force : '')).trim().toLowerCase();
const content = first
  + (form ? '\n\n---\n\nThe form chosen for this visual is `' + form + '`. Every option plans that form; do not substitute another.' : '');
return [{ json: {
  ...a,
  PLANS_BODY: JSON.stringify({ ...body, task: 'plans', form, options: 3, messages: [{ role: 'user', content }] }),
} }];

// The storyboard options the composer returned, and the critic's request. Each option was
// already validated by the adapter; a rejected one is named in PLANS_ERROR and the valid
// ones still travel.
const a = $('build_plans_brief').last().json || {};
const r = $input.first().json || {};
const plans = Array.isArray(r.plans) ? r.plans : [];
const failure = r.error && (r.error.message || r.error);
const error = plans.length ? String(r.error || '') : String(failure || 'the plans turn returned no options');
const prompt = String($('download_plan_options_review_prompt').first().json.output || '').trim();
if (!prompt) throw new Error('the plan-options review prompt is empty; refusing to review the plans');
let body = {};
try { body = JSON.parse(String(a.AUTHOR_BODY || '{}')); } catch (e) { body = {}; }
const brief = String((((body.messages || [])[0] || {}).content) || '');
const human = String(a.HUMAN_FEEDBACK || a.FEEDBACK || '').trim();
const form = String(a.FORM || '').trim().toLowerCase();
const optionsText = plans.length ? JSON.stringify(plans, null, 2) : '';
const review = [
  prompt,
  '',
  '---',
  '',
  'The post text, the source and the rules the visual is for:',
  brief,
  ...(human ? ['', '---', '', 'Feedback from the person - a requirement:', human] : []),
  ...(form ? ['', '---', '', 'The form chosen for this visual:', form] : []),
  ...(optionsText ? ['', '---', '', "The composer's storyboard options:", optionsText] : ['', '---', '', 'The composer returned no parsable storyboard options.']),
].join('\n');
return [{ json: {
  ...a,
  PLAN_OPTIONS: JSON.stringify(plans),
  PLANS_ERROR: error,
  PLANS_REVIEW_BODY: JSON.stringify({ model: 'opencode-go/minimax-m3', messages: [{ role: 'user', content: review }] }),
} }];

// The plan critic's choice. A valid id is approved for authoring without the single-plan
// retry; an unreadable answer takes the first valid option and marks the fallback. With no
// valid option, PLAN_APPROVED stays false and the single-plan gate runs instead.
const a = $('parse_plans').last().json || {};
const resp = $input.first().json || {};
const raw = String((((resp.choices || [])[0] || {}).message || {}).content || '').trim();
let answer = null;
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
if (start !== -1 && end > start) {
  try { const parsed = JSON.parse(raw.slice(start, end + 1)); if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) answer = parsed; } catch (e) { answer = null; }
}
const plans = (() => {
  try { const parsed = JSON.parse(String(a.PLAN_OPTIONS || '[]')); return Array.isArray(parsed) ? parsed : []; } catch (e) { return []; }
})();
const choice = answer ? String(answer.choice || '').trim() : '';
const named = plans.find((option) => option && option.id === choice) || null;
const chosen = named || plans[0] || null;
const plan = chosen && chosen.plan && typeof chosen.plan === 'object' ? chosen.plan : null;
// No option at all is also a fallback: the single-plan path runs and the asset records it.
const fallback = !named;
return [{ json: {
  ...a,
  PLAN_OPTIONS: JSON.stringify(plans),
  PLAN_CHOICE: chosen ? String(chosen.id) : '',
  PLAN: plan ? JSON.stringify(plan) : '',
  PLAN_APPROVED: Boolean(plan),
  PLAN_VERDICT: plan ? 'options' : 'unread',
  PLAN_ERROR: plan ? '' : (String(a.PLANS_ERROR || '') || 'the plan-options stage returned no valid plan'),
  FORM: plan ? String(plan.form || a.FORM || '') : String(a.FORM || ''),
  OPTIONS_FALLBACK: a.OPTIONS_FALLBACK === true || fallback,
  NEEDS_REVIEW: a.NEEDS_REVIEW === true || fallback,
  PLAN_RETRY: false,
  PLAN_EXHAUSTED: false,
} }];

normalize_input.parameters.jsCode:
const raw = $input.first().json || {};
const src = Object.assign({}, raw.body || {}, raw.query || {}, raw);
const v = (k) => { const x = src[k]; return x == null ? '' : String(x).trim(); };
const content = v('CONTENT');
if (!content) throw new Error('CONTENT is required');
// FORCE pins the form; STYLE names a brand scheme and is resolved (and defaulted)
// in brand_tokens, where the scheme names live, so an unknown value fails there.
const FORCES = ['auto', 'diagram', 'story', 'data', 'poster', 'code', 'chart', 'timeline', 'quote', 'ui', 'manga', 'retro', 'launch', 'tiles', 'sketch'];
const force = v('FORCE') || 'auto';
if (!FORCES.includes(force)) throw new Error('unknown FORCE: ' + force + ' (expected one of ' + FORCES.join(', ') + ')');
// An optional scene plan: a list-shaped article asks for one item per scene. A blank
// or non-positive value leaves the scene count to the composer's own storyboard.
const scenesRaw = parseInt(v('SCENES'), 10);
const scenes = (isFinite(scenesRaw) && scenesRaw > 0) ? Math.min(scenesRaw, 12) : '';
// How many review turns one asset may spend before it ships with its findings recorded.
const REVIEW_CYCLES = 3;
return [{ json: {
  REVIEW_ROUND: 0,
    REVIEW_CYCLES,
    RUN_ID: String($execution.id),
  CONTENT: content,
  ASSET_TYPES: v('ASSET_TYPES'),
  FEEDBACK: v('FEEDBACK'),
  // The person's feedback, kept apart from the critic's corrections so a review
  // turn cannot lose it.
  HUMAN_FEEDBACK: v('FEEDBACK'),
  // Free text the caller owns, appended to the brief after the content and the
  // rules. Never parsed.
  EXTRA_PROMPT: v('EXTRA_PROMPT'),
  // A session to continue, when the caller names one. Blank means this run is a
  // first authoring, with an identifier scoped to the run so it stays isolated.
  SESSION_ID: v('SESSION_ID'),
  FORCE: force,
  SCENES: scenes,
  // The post writer's form and scene count are hints for the form stage, never a
  // force: a row pin arrives as FORCE and wins.
  SUGGESTED_FORM: v('SUGGESTED_FORM'),
  SUGGESTED_SCENES: v('SUGGESTED_SCENES'),
  STYLE: v('STYLE'),
} }];

build_author_brief.parameters.jsCode:
// Turn the request into the composer's brief and the session request. The brief is
// the caller's CONTENT, the requested form and style, the type's declared frame, the
// shared motion rules and any correction or extra direction the caller supplied.
// Whether a turn authors or edits is the adapter's call, taken from the session
// directory itself; the brief never claims one, so a named session with no directory
// is not told to keep a composition that does not exist.
// A caller that names a session is used as given; a caller that names none gets an
// id scoped to this run, so a later run cannot overwrite its artifact before it is
// fetched. Everything here is data-driven, so a type is retuned from the registry
// without touching the adapter.
const a = $input.first().json;
const req = $('normalize_input').first().json;
const brand = $('brand_tokens').first().json;
const rules = String($('visual_rules').first().json.RULES || '').trim();
const sceneText = String($('scene_rules').first().json.SCENE || '').trim();
const safe = (s) => String(s || '').replace(/[^A-Za-z0-9._-]/g, '').slice(0, 40);
// A named session is used as given; a blank one is scoped to this run.
const sessionId = safe(req.SESSION_ID) || (safe(a.ASSET_TYPE) + '-' + safe(req.RUN_ID)) || 'default';
const base = ($env.PI_RENDER_URL || '').replace(/\/+$/, '');
const utils = ($env.MCP_UTILS_URL || '').replace(/\/+$/, '');
// A deck is authored as one self-contained HTML file; the same turn renders it to
// the paired video, so no transcode happens after the turn.
const isDeck = String(a.RENDER_MODE || '') === 'deck';
const FORMATS = ['mp4', 'gif', 'webp', 'png', 'svg'];
const format = isDeck ? 'html' : (FORMATS.includes(a.FORMAT) ? a.FORMAT : 'mp4');
// The container is the request's, never this node's invention. A review turn's item is
// asset-shaped and carries the request's declaration (agent_result copies it onto the
// asset), so a correction turn keeps the container of the turn it corrects. Before this
// the four silent defaults below fired at once and a tiles_wide request (16:9 / 1280 /
// 12s / 360) was corrected at 1080x1350 / 3s / 24 frames (measured 2026-10-17, run
// 13785). A missing declaration is an error naming the field: a plausible default is
// indistinguishable from the caller's request once the run has produced an artifact.
const declared = (field, value) => {
  const n = Number(value);
  if (!Number.isFinite(n) || n <= 0) throw new Error('the request declared no ' + field + '; the authoring brief cannot re-declare a container');
  return n;
};
const aspectMatch = /^([0-9.]+):([0-9.]+)$/.exec(String(a.ASPECT || '').trim());
if (!aspectMatch || !(Number(aspectMatch[1]) > 0) || !(Number(aspectMatch[2]) > 0)) {
  throw new Error('the request declared no ASPECT; the authoring brief cannot re-declare a container');
}
const aw = Number(aspectMatch[1]);
const ah = Number(aspectMatch[2]);
const width = declared('VIEWPORT', a.VIEWPORT);
const height = Math.round(width * ah / aw);
// A type may declare the shape it means -- a diagram type is a diagram -- and that is
// stronger than the caller's FORCE, because choosing the type is choosing its shape.
// A type that declares none takes the caller's FORCE; with neither, the composer chooses.
const force = String(a.FORM || req.FORCE || 'auto');
// The form vocabulary is one committed file, fetched like the motion rules and
// appended to the brief so a forced form arrives with its meaning; the workflow does
// not restate the definitions.
const forms = String($('visual_forms').first().json.FORMS || '').trim();
const vocab = forms ? ['Form vocabulary:', forms] : [];
const form = force === 'auto'
  ? 'Choose the form that fits the content best.'
  : 'Use the ' + force + ' form; do not substitute another.';
const scenes = Math.max(0, Math.round(Number(req.SCENES) || 0));
// One declared scene is the whole clip. A longer sequence opens on a title scene
// that names the subject, so it is introduced rather than starting cold; the
// caller's scenes follow it, and the clip carries one more scene than was asked.
const sceneLine = scenes > 0
  ? 'Render exactly ' + scenes + ' scenes, one item per scene, in the order the storyboard sets'
    + (scenes > 1 ? ', opening on a title scene that names the subject before them (' + (scenes + 1) + ' scenes in all).' : '.')
  : '';
// A counted sequence is introduced above. A clip whose content scenes are the composer's
// own still needs its subject named first: run 14335 opened on a detail, and only a human
// retry asked for the title. The type declares that it sequences content; a loop does not.
const introLine = scenes === 0 && a.INTRO_SCENE === true
  ? 'Open on a title scene that names the subject - the company, product or technology the post is about - before the content scenes the storyboard sets.'
  : '';
// The scene contract is a prompt file, not a count: what a scene is, and where the title
// sits, is read there. It applies to every branch that carries scenes.
const sceneBlock = sceneText ? ['How scenes work:', sceneText] : [];
// The declared duration is the floor. A caller that names a scene count gives each
// scene at least the type's declared scene length, so a multi-scene clip is never
// compressed into the single-scene time.
const declaredFrames = Math.max(1, declared('FRAMES', a.FRAMES));
const declaredSeconds = Math.max(1, declared('DURATION_SECONDS', a.DURATION_SECONDS));
const sceneSeconds = Math.max(0, Number(a.SCENE_SECONDS) || 0);
const seconds = Math.max(declaredSeconds, scenes * sceneSeconds);
// Extending the clip keeps the declared sampling rate instead of speeding it up.
const frames = seconds > declaredSeconds ? Math.max(1, Math.round(declaredFrames * seconds / declaredSeconds)) : declaredFrames;
const rate = Math.max(0.1, frames / seconds);
const planLine = 'Plan first: state a short storyboard with the form, the scenes and the order they play in, then author the composition.';
const deckPlanLine = 'Plan first: state a short plan with the arc and the per-slide content, then author the deck to it.';
const stillPlanLine = 'Plan first: state the card in one line - the brand lockup, the headline, the supporting line, the feature chips, the interface window and the call to action - then author the composition.';
const stillSceneLine = scenes > 0 ? 'The card carries the declared ' + scenes + ' items as that many parts of the same card, in the order given; they are not sequenced over time.' : '';
const sampling = ['gif', 'webp'].includes(format)
  ? 'Animate slowly and deliberately: reveal a few elements in sequence, each held long enough to read, rather than many quick changes. The clip is sampled into a low-frame-rate file, so fast or busy motion is lost.'
  : 'Animate deliberately: a few clear beats, each held long enough to read, rather than many quick changes.';
const styleLine = 'Style: use the brand\'s ' + brand.STYLE + ' scheme; do not introduce a colour or typeface the brand block below does not define.';
// Appended last, in this order: the shared motion rules (the framework's craft, one
// committed copy), a reviewer's correction when one is present, and the caller's
// extra direction when one is present. Nothing here is parsed; all three are prose
// the composer reads.
const tail = [];
if (rules) tail.push('Motion rules (apply to every scene):', rules);
const human = String(a.HUMAN_FEEDBACK || req.HUMAN_FEEDBACK || '').trim();
const feedback = String(a.FEEDBACK || '').trim();
if (feedback && feedback !== human) tail.push('Correction from a reviewer - fix this in this attempt:', feedback);
if (req.EXTRA_PROMPT) tail.push('Extra direction from the caller:', req.EXTRA_PROMPT);
// The person's requirements and the approved plan come first. Buried after the content and the
// rules they are the block a later turn loses, and the 17587 render lost exactly that.
const planText = String(a.PLAN || '').trim();
const planPretty = (() => { try { return JSON.stringify(JSON.parse(planText), null, 2); } catch (e) { return planText; } })();
const preamble = [
  ...(human ? ['Feedback from the person - a requirement for this attempt:', human, ''] : []),
  ...(planPretty ? ['Approved plan (the storyboard the review accepted; write to it):', planPretty, ''] : []),
  ...(a.PLAN_ERROR ? ['The plan review did not approve this plan:', String(a.PLAN_ERROR), ''] : []),
];
const brandBlock = ['', 'Brand block:', brand.BRAND];
const brief = isDeck
  ? [
      ...preamble,
      req.CONTENT,
      '',
      deckPlanLine,
      sceneLine,
      ...sceneBlock,
      'Author ONE self-contained HTML presentation and write it to `out.html` in this directory: a single file with no external stylesheet, script, font or network request, whose navigation works with no server. Preserve the text\'s own structure, one idea per slide.',
      'Then author a HyperFrames composition of that same plan to `index.html` and render it to `out.mp4` in this same directory, at ' + width + 'x' + height + ' (' + a.ASPECT + ') over about ' + seconds + ' seconds, so the slides and their order match the deck.',
      styleLine,
      ...tail,
      ...brandBlock,
    ].join('\n')
  : format === 'svg'
  ? [
      ...preamble,
      req.CONTENT,
      '',
      'Author ONE self-contained animated SVG and write it to `out.svg`. Do not render and do not write index.html.',
      form,
      ...vocab,
      sceneLine,
      ...sceneBlock,
      styleLine,
      'Use a ' + width + 'x' + height + ' (' + a.ASPECT + ') viewBox.',
      'Animate with CSS @keyframes inside a <style> element, or with SMIL; no external stylesheet, no script, no network. Reveal a few elements in sequence, each held long enough to read.',
      'Reference the brand typefaces by name with a system fallback, and keep the file well-formed XML with every animated element ending visible.',
      ...tail,
      ...brandBlock,
    ].join('\n')
  : format === 'png'
  ? [
      ...preamble,
      req.CONTENT,
      '',
      stillPlanLine,
      form,
      ...vocab,
      stillSceneLine,
      styleLine,
      'Compose ONE still card at ' + width + 'x' + height + ' (' + a.ASPECT + '), with the whole card complete and legible in the final frame of the composition.',
      'Entrances may run, but nothing may leave, dim or hide before the end: the artifact is that final frame, so everything the card carries must still be there in it.',
      ...tail,
      ...brandBlock,
    ].join('\n')
  : [
      ...preamble,
      req.CONTENT,
      '',
      planLine,
      form,
      ...vocab,
      sceneLine,
      introLine,
      ...sceneBlock,
      styleLine,
      'Render a ' + width + 'x' + height + ' (' + a.ASPECT + ') composition that runs about ' + seconds + ' seconds.',
      sampling,
      ...tail,
      ...brandBlock,
    ].join('\n');
const pairedFormat = isDeck ? (a.PAIRED_FORMAT || 'mp4') : '';
return [{ json: Object.assign({}, a, {
  FORCE: force, SCENES: scenes, STYLE: brand.STYLE,
  REVIEW_ROUND: Math.max(0, Number(a.REVIEW_ROUND || 0)),
  FORMAT: format, FPS: rate, WIDTH: width, HEIGHT: height, FRAMES: frames, DURATION_SECONDS: seconds, RATE: rate,
  SESSION_ID: sessionId,
  FORM_OPTIONS: String(a.FORM_OPTIONS || '[]'),
  FORM_CHOICE: String(a.FORM_CHOICE || ''),
  PLAN_OPTIONS: String(a.PLAN_OPTIONS || '[]'),
  PLAN_CHOICE: String(a.PLAN_CHOICE || ''),
  OPTIONS_FALLBACK: a.OPTIONS_FALLBACK === true,
  AUTHOR_URL: base ? base + '/v1/chat/completions' : '',
  ARTIFACT_URL: base ? base + '/artifacts/' + sessionId + '/out.' + format : '',
  ARTIFACT_KEY: 'visual-studio/' + safe(req.RUN_ID) + '-' + safe(a.ASSET_TYPE) + '.' + format,
  STORE_URL: utils ? utils + '/mcp' : '',
  PAIRED_FORMAT: pairedFormat,
  PAIRED_ARTIFACT_URL: (isDeck && base) ? base + '/artifacts/' + sessionId + '/out.' + pairedFormat : '',
  PAIRED_ARTIFACT_KEY: isDeck ? 'visual-studio/' + safe(req.RUN_ID) + '-' + safe(a.ASSET_TYPE) + '.' + pairedFormat : '',
  AUTHOR_BODY: JSON.stringify({ messages: [{ role: 'user', content: brief }], session_id: sessionId, format: format, fps: rate, width: width, height: height, frames: frames, durationSeconds: seconds }),
}) }];

agent_result.parameters.jsCode:
// The rendered artifact(s) the session produced, as the asset, plus the composer's own
// report kept as STORYBOARD so a bad visual is diagnosable from the run record. The
// bytes are deliberately not here: the temp-bucket server fetched each artifact from
// the session and stored it, and what comes back is the object key and its size. That
// is what keeps a 60 MB render out of this execution's record - n8n persists binaries
// as well as JSON, so a run whose payload is the asset stores the asset twice. The
// workflow never sees the agent's composition markup, only this report. A deck is two
// files from one turn, so two stores ran and two assets come out.

// The authoring call's own verdict. A pre-turn failure (a staging error, an unreadable
// workspace) and an exhausted Pi window both answer 400 with the reason in the body, and
// `neverError` delivers that body as data; a transport failure arrives on this node's error
// output instead. Without this the asset reports the store's 404 on an artifact that was
// never rendered, which names the symptom rather than the cause (measured 2026-10-24,
// execution 14801: the form said `/artifacts/lips-106/out.mp4 answered HTTP 404` when the
// session had answered `EEXIST: file already exists, mkdir ...`).
// A 4xx body arrives as data on output 0 (`neverError`) and a transport failure or node
// timeout as an item carrying `error` on output 1 (`continueErrorOutput`). Reading only
// output 0 lost the reason: on 2026-11-14 (execution 16743) a 40-minute authoring timeout
// reached the asset as the store node's absence.
const authorOut = (() => {
  const pick = (i) => { try { return $('execute_author').all(i)[0] || {}; } catch (e) { return {}; } };
  const item = pick(0);
  const failed = pick(1);
  const e = (failed.json && failed.json.error) || (item.json && item.json.error);
  const message = typeof e === 'string' ? e
    : e && typeof e.message === 'string' ? e.message
    : e ? JSON.stringify(e) : '';
  return { body: item.json || {}, error: message };
})();
const authorError = authorOut.error;
const a = $('build_author_brief').last().json;
const report = (() => {
  try {
    const resp = authorOut.body;
    const msg = resp.choices && resp.choices[0] && resp.choices[0].message;
    const content = msg && msg.content;
    return typeof content === 'string' ? content.slice(0, 6000) : '';
  } catch (e) { return ''; }
})();
// What the session reported about the artifact's container. The declared values below are
// the request's, which the conformance in the session makes the artifact's by construction;
// this is what it was actually served at, and it names the authored frame where the two
// differed (measured 2026-10-17, run 13762: a 16:9 / 12s type served at 1080x1350 / 3s).
const conformance = (() => {
  try {
    const resp = authorOut.body;
    const c = resp.conformance;
    return c && typeof c === 'object' ? c : {};
  } catch (e) { return {}; }
})();
// The adapter's deterministic gate, its motion readings and its connector report, read the
// same defensive way: an adapter that predates them arrives as {}, and a raster path that
// runs no gate is recorded rather than read as clean.
const bodyField = (name) => {
  try {
    const f = authorOut.body && authorOut.body[name];
    return f && typeof f === 'object' ? f : {};
  } catch (e) { return {}; }
};
const checkReport = bodyField('check');
const signals = bodyField('signals');
const connectors = bodyField('connectors');
const base = {
  ASSET_TYPE: a.ASSET_TYPE, RENDER_MODE: a.RENDER_MODE || '', FORMAT: a.FORMAT || '',
  FORM: a.FORM || '',
  STATUS: '', PROMPT: '', CONTENT_TYPE: '', ERROR: '', STORYBOARD: report,
  // The container the request declared, carried on the asset beside what the runtime
  // delivered. The review loop builds its items from this asset, so a correction turn
  // reads the declaration here instead of re-inventing one (measured 2026-10-17, run
  // 13785: a 16:9 / 12s / 360-frame type was corrected at 1080x1350 / 3s / 24 frames
  // because these five were absent from the asset).
  ASPECT: a.ASPECT || '', VIEWPORT: String(Number(a.VIEWPORT) || ''),
  INTRO_SCENE: a.INTRO_SCENE === true,
  FRAMES: String(Number(a.FRAMES) || ''), DURATION_SECONDS: String(Number(a.DURATION_SECONDS) || ''),
  FPS: String(Number(a.FPS) || ''),
  DURATION_MS: String(Math.round((Number(a.DURATION_SECONDS) || 0) * 1000)),
  FRAME_COUNT: String(Number(a.FRAMES) || ''), WIDTH: a.WIDTH || '', HEIGHT: a.HEIGHT || '',
  CONFORMED: conformance.fit || '', AUTHORED_FRAME: conformance.authored || '', SHORT: conformance.short === true,
  IMAGE: '', S3_KEY: '', S3_BYTES: 0,
  // The gate's report and the review's ledger ride on the asset. OPEN_FINDINGS and STALLED are
  // the previous turn's, carried here through the correction loop (review_feedback ->
  // build_author_brief -> this node), so a finding keeps its id and its count across rounds.
  SCENES: String(Number(a.SCENES) || ''),
  CHECK: JSON.stringify(checkReport), CHECK_OK: checkReport.ok === true, CHECK_REASON: checkReport.reason || '',
  SIGNALS: JSON.stringify(signals), CONNECTORS: JSON.stringify(connectors),
  MOTION_GATE: checkReport.ran ? 'ran' : 'absent',
  SHEET: String(authorOut.body && authorOut.body.sheet || ''),
  OPEN_FINDINGS: a.OPEN_FINDINGS || '[]', STALLED: a.STALLED || '[]',
  HUMAN_FEEDBACK: a.HUMAN_FEEDBACK || '', PLAN: a.PLAN || '', PLAN_APPROVED: a.PLAN_APPROVED === true, PLAN_ERROR: a.PLAN_ERROR || '',
  FORM_OPTIONS: a.FORM_OPTIONS || '[]', FORM_CHOICE: a.FORM_CHOICE || '', FORM_WHY: a.FORM_WHY || '',
  PLAN_OPTIONS: a.PLAN_OPTIONS || '[]', PLAN_CHOICE: a.PLAN_CHOICE || '',
  OPTIONS_FALLBACK: a.OPTIONS_FALLBACK === true,
  VERDICT: '', NEEDS_REVIEW: Boolean(a.PLAN_ERROR) || a.OPTIONS_FALLBACK === true,
};
const describe = (v, fallback) => {
  if (typeof v === 'string' && v) return v;
  if (v && typeof v === 'object' && typeof v.message === 'string') return v.message;
  if (v != null) return JSON.stringify(v);
  return fallback;
};
// One store answer: `key=<object> bytes=<size> content-type=<type>`, or a line starting
// ERROR:. Split the way a caller does - whitespace, then the first '=' - so a change to
// prose on the server arrives here as a missing key rather than a silently wrong value.
const stored = (node) => {
  try {
    const resp = $(node).first().json || {};
    const content = resp.result && resp.result.content;
    const text = content && content[0] && content[0].text;
    if (typeof text !== 'string') return { ERROR: 'the temp-bucket server answered no text' };
    if (text.indexOf('ERROR:') === 0) return { ERROR: text.slice(0, 500) };
    const pairs = {};
    for (const part of text.trim().split(/\s+/)) {
      const eq = part.indexOf('=');
      if (eq > 0) pairs[part.slice(0, eq)] = part.slice(eq + 1);
    }
    if (!pairs.key) return { ERROR: 'the temp-bucket server answered no key: ' + text.slice(0, 400) };
    return { KEY: pairs.key, BYTES: Number(pairs.bytes || 0), CONTENT_TYPE: pairs['content-type'] || '' };
  } catch (e) {
    // The node did not run at all, which for the paired store means this is not a deck.
    return { ERROR: describe(e && e.message, 'the artifact was not stored') };
  }
};
if (!a.AUTHOR_URL) {
  return [{ json: Object.assign({}, base, { STATUS: 'ERROR', ERROR: 'PI_RENDER_URL is not configured' }) }];
}
if (!a.STORE_URL) {
  return [{ json: Object.assign({}, base, { STATUS: 'ERROR', ERROR: 'MCP_UTILS_URL is not configured' }) }];
}
const primary = stored('store_artifact');
const items = [primary.KEY
  ? Object.assign({}, base, {
      STATUS: 'RENDERED', CONTENT_TYPE: primary.CONTENT_TYPE || 'application/octet-stream',
      S3_KEY: primary.KEY, S3_BYTES: primary.BYTES,
    })
  : Object.assign({}, base, { STATUS: 'ERROR', ERROR: authorError ? `authoring failed: ${authorError}` : primary.ERROR })];
// A deck's paired video is stored by its own call, after the deck itself.
if (a.PAIRED_ARTIFACT_URL) {
  const paired = stored('store_paired_artifact');
  const pairedBase = Object.assign({}, base, {
    ASSET_TYPE: a.PAIRED_ASSET_TYPE || (a.ASSET_TYPE + '_video'),
    RENDER_MODE: 'video', FORMAT: a.PAIRED_FORMAT || 'mp4', PAIRED_OF: a.ASSET_TYPE,
  });
  items.push(paired.KEY
    ? Object.assign({}, pairedBase, {
        STATUS: 'RENDERED', CONTENT_TYPE: paired.CONTENT_TYPE || 'video/mp4',
        S3_KEY: paired.KEY, S3_BYTES: paired.BYTES,
      })
    : Object.assign({}, pairedBase, { STATUS: 'ERROR', ERROR: authorError ? `authoring failed: ${authorError}` : paired.ERROR }));
}
// An asset that never rendered was never reviewed, so it cannot leave here looking clean.
return items.map((json) => ({ json: json.STATUS === 'ERROR'
  ? Object.assign({}, json, { NEEDS_REVIEW: true, VERDICT: 'unread' })
  : json }));

build_plan_brief.parameters.jsCode:
// The plan turn asks the same session for the storyboard before it authors. The brief is the
// authoring brief, with the person's feedback already at the top and a previous plan round's
// findings appended. The container fields ride along because the session validates them; the
// plan turn ignores them and writes and renders nothing.
const a = $input.first().json || {};
let body = {};
try { body = JSON.parse(String(a.AUTHOR_BODY || '{}')); } catch (e) { body = {}; }
const first = ((body.messages || [])[0] || {}).content;
if (!first) throw new Error('the plan turn has no authoring brief to plan from');
const feedback = String(a.PLAN_FEEDBACK || '').trim();
// A fallback from the form stage still carries its chosen form, so the single plan is
// planned for that form instead of choosing one the authoring turn will then overrule.
const chosen = String(a.FORM || '').trim().toLowerCase();
const formLine = a.FORM_OPTIONS && chosen
  ? '\n\n---\n\nThe form chosen for this visual is `' + chosen + '`. Plan that form; do not substitute another.'
  : '';
const content = (feedback
  ? first + '\n\n---\n\nThis plan is a revision. The plan review named these problems; fix them and return the whole plan again:\n' + feedback
  : first) + formLine;
return [{ json: {
  ...a,
  PLAN_ROUND: Math.max(0, Number(a.PLAN_ROUND || 0)),
  PLAN_FEEDBACK: feedback,
  PLAN_BODY: JSON.stringify({ ...body, task: 'plan', messages: [{ role: 'user', content }] }),
} }];

check_animation_result.parameters.jsCode:
// The studio's own run STATUS is PARTIAL whenever a requested type is unavailable, so the
// asset's status is what this branches on. The LinkedIn branch asks the studio for the
// composer-authored video type; both animated opt-ins (ANIMATED, AGENT) share it.
// `poster_gif` is still accepted, because a caller may request it explicitly.
// The asset is located by its object key rather than by a data URL: the studio stores
// the render in the temp bucket through the utils MCP server and never carries its
// bytes, which is what keeps a 60 MB asset out of the studio's execution record.
const r = $input.first().json || {};
const assets = r.ASSETS || [];
const want = ['animation_linkedin_video', 'poster_gif'];
const expected = 'animation_linkedin_video';
const a = assets.find((x) => want.includes(x.ASSET_TYPE)) || null;
const ok = Boolean(a && a.STATUS === 'RENDERED' && a.S3_KEY);
const planError = String((a && a.PLAN_ERROR) || '').trim();
// The review's own state, so the approval can name what is still open instead of presenting a
// `fix` asset as one the review passed.
const open = (() => {
  try {
    const parsed = JSON.parse(String((a && a.OPEN_FINDINGS) || '[]'));
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) { return []; }
})();
// The stage records ride on the asset so the approval can name the chosen form and plan,
// and say when a stage could not decide and fell back to the first valid option.
const fallback = a ? a.OPTIONS_FALLBACK === true : false;
// The single-plan path has no FORM_CHOICE: its form is inside PLAN, and the approval
// names it rather than reporting no form.
const planForm = (() => {
  try {
    const plan = JSON.parse(String((a && a.PLAN) || '{}'));
    return plan && typeof plan.form === 'string' ? plan.form : '';
  } catch (e) { return ''; }
})();
return [{ json: {
  RUN_ID: r.RUN_ID || '',
  RUN_STATUS: r.STATUS || '',
  ASSET_TYPE: a ? a.ASSET_TYPE : '',
  ASSET_STATUS: a ? a.STATUS : 'MISSING',
  CONTENT_TYPE: a ? (a.CONTENT_TYPE || '') : '',
  S3_KEY: a && a.S3_KEY ? a.S3_KEY : '',
  DURATION_MS: a ? (a.DURATION_MS || '') : '',
  FRAME_COUNT: a ? (a.FRAME_COUNT || '') : '',
  VERDICT: a ? (a.VERDICT || '') : '',
  NEEDS_REVIEW: (a ? a.NEEDS_REVIEW === true : false) || Boolean(planError) || fallback,
  OPEN_COUNT: open.length,
  OPEN_FINDINGS: a ? (a.OPEN_FINDINGS || '[]') : '[]',
  STALLED: a ? (a.STALLED || '[]') : '[]',
  CHECK_OK: a ? a.CHECK_OK === true : false,
  CHECK_REASON: a ? (a.CHECK_REASON || '') : '',
  PLAN_APPROVED: a ? a.PLAN_APPROVED === true : false,
  PLAN_ERROR: planError,
  FORM: a ? (a.FORM || planForm) : '',
  FORM_CHOICE: a ? (a.FORM_CHOICE || '') : '',
  PLAN_CHOICE: a ? (a.PLAN_CHOICE || '') : '',
  OPTIONS_FALLBACK: fallback,
  ERROR: ok ? '' : ('animated media unavailable (expected ' + expected + '): ' + ((a && (a.ERROR || a.STATUS)) || 'no asset returned')),
} }];

build_hook_columns.parameters.jsCode:
// The writer classified on this turn, so its HOOK becomes the row's, written before the
// text approval. Its form and scene count are hints, not decisions: they ride along as
// SUGGESTED_FORM/SUGGESTED_SCENES and the studio's form stage weighs them. Only HOOK is
// written back, so a non-empty VISUAL_FORM on the row is a person's pin (FORM_PIN) and a
// writer's answer can never become a pin on the next run. Both status columns stay
// untouched; a Cancel at the approval leaves these cells and the row is CANCELED there anyway.
const row = $('select_article_to_post').first().json;
const draft = $('execute_post_creator').first().json || {};
const HOOK = String(draft.HOOK || '').trim().toUpperCase();
const SUGGESTED_FORM = String(draft.VISUAL_FORM || '').trim().toLowerCase();
const SUGGESTED_SCENES = String(draft.SCENES == null ? '' : draft.SCENES).trim();
// A row cell is read at run start, before this node writes anything: a non-empty
// VISUAL_FORM is a human edit, never this workflow's own previous answer.
const FORM_PIN = String(row.VISUAL_FORM || '').trim().toLowerCase();
const SCENES_PIN = String(row.SCENES == null ? '' : row.SCENES).trim();
// The video's session is the article, not the sheet row: expiring rows renumber the
// queue, so a reused row number would edit the previous article's composition in place.
const url = String(row.URL || '').trim();
if (!url) throw new Error('the row carries no URL: the video session cannot be named');
const hashed = [...url].reduce((h, ch) => Math.imul(h ^ ch.codePointAt(0), 16777619), 2166136261);
const STUDIO_SESSION_ID = 'lips-' + (hashed >>> 0).toString(36);
if (!HOOK) {
  throw new Error('the post creator returned no hook: row ' + row.row_number + ' would publish without its classification');
}
row.HOOK = HOOK;
console.log('build_hook_columns: row ' + row.row_number + ' ' + HOOK
  + ' / hint ' + (SUGGESTED_FORM || 'auto') + ' / scenes ' + (SUGGESTED_SCENES || '0')
  + (FORM_PIN ? ' / pin ' + FORM_PIN : ''));
return [{ json: { row_number: row.row_number, HOOK, SUGGESTED_FORM, SUGGESTED_SCENES, FORM_PIN, SCENES_PIN, STUDIO_SESSION_ID } }];
